data.value:
CREATE TABLE IF NOT EXISTS knowledge_revisions (
    category TEXT NOT NULL, entity_id TEXT NOT NULL, revision_id TEXT NOT NULL,
    known_ticks BIGINT NOT NULL, hash TEXT NOT NULL, payload TEXT NOT NULL,
    PRIMARY KEY(category,entity_id,revision_id), UNIQUE(category,entity_id,known_ticks));
CREATE INDEX IF NOT EXISTS ix_knowledge_asof ON knowledge_revisions(category,known_ticks);

CREATE TABLE IF NOT EXISTS material_versions (
    material_id TEXT NOT NULL, version_id TEXT NOT NULL,
    source_id TEXT NOT NULL, kind TEXT NOT NULL,
    known_at_ticks BIGINT NOT NULL, corrects_version_id TEXT,
    content_hash TEXT NOT NULL, payload_json TEXT NOT NULL,
    PRIMARY KEY(material_id,version_id),
    FOREIGN KEY(material_id,corrects_version_id) REFERENCES material_versions(material_id,version_id) DEFERRABLE INITIALLY IMMEDIATE
);
CREATE TABLE IF NOT EXISTS material_companies (
    material_id TEXT NOT NULL, version_id TEXT NOT NULL, company_id TEXT NOT NULL,
    PRIMARY KEY(material_id,version_id,company_id),
    FOREIGN KEY(material_id,version_id) REFERENCES material_versions(material_id,version_id) DEFERRABLE INITIALLY IMMEDIATE
);
CREATE INDEX IF NOT EXISTS ix_materials_known ON material_versions(kind,known_at_ticks);
CREATE INDEX IF NOT EXISTS ix_material_companies ON material_companies(company_id);
